	"data-role", "onclick",
	"aria-expanded", "aria-haspopup", "aria-controls",
)
_INTERACTIVE_ROLES = {"button", "menu", "menubar", "menuitem", "tab", "option", "listbox", "tree", "treeitem"}


def _click_effect_watch_target(tag: str, attrs: dict) -> bool:
	if tag == "BUTTON":
		return True
	if tag == "INPUT":
		return attrs.get("type") in ("submit", "button")
	if tag == "A":
		return False
	if attrs.get("tabindex") == "-1":
		return False
	if attrs.get("role") not in _INTERACTIVE_ROLES:
		attrs = {k: v for k, v in attrs.items() if k != "role"}
	if "data-bind" in attrs and not re.search(r"click|toggle|event", attrs["data-bind"] or ""):
		attrs = {k: v for k, v in attrs.items() if k != "data-bind"}
	return any(k in attrs for k in _INTERACTIVE_ATTR_MARKERS)

